USE [Petrovendor]GOIF EXISTS(    SELECT 1    FROM dbo.sysobjects    WHERE name = 'SP_MM_ConsultaIdTareaPorPedido')    DROP PROCEDURE SP_MM_ConsultaIdTareaPorPedido;/****** Object:  StoredProcedure [dbo].[SP_MM_ConsultaIdTareaPorPedido]    Script Date: 12/04/2022 02:18:33 p. m. ******/SET ANSI_NULLS ONGOSET QUOTED_IDENTIFIER ONGO-- =============================================-- Author: Daniel AC-- Create date: 12-04-2022-- Description:	 Se actualiza información para retornar el no de tarea correctamente -- =============================================CREATE procedure [dbo].[SP_MM_ConsultaIdTareaPorPedido]	@IdSolicitudPedido INT,	@Version INT,    @IdContrato    INT = null, 	@IdUsuario     INT,    @FechaRegistro DATETIME = nullASBEGIN	SELECT t.IdTarea	FROM MM_Pedido P	JOIN dbo.TA_Operacion O ON	P.IdSolicitudPedido  = O.IdDocumento	AND P.Version =O.NoVersion	JOIN dbo.TA_Tarea T	ON  O.IdOperacion = T.IdOperacion	WHERE P.IdSolicitudPedido = @IdSolicitudPedido	AND O.IdTipoOperacion = 9 --> CTE APROBACION DE PEDIDO	AND O.NoVersion=@Version	AND T.IdAprobador=@IdUsuario	AND ISNULL(t.Activo,0)=1 --> CTE DEBE ESTAR ACTIVA LA TAREA	GROUP BY t.IdTareaENDUSE [Petrovendor]GOIF EXISTS(    SELECT 1    FROM dbo.sysobjects    WHERE name = 'SP_RPT_OCM_AprobadoresPorPedido')    DROP PROCEDURE SP_RPT_OCM_AprobadoresPorPedido;/****** Object:  StoredProcedure [dbo].[SP_RPT_OCM_AprobadoresPorPedido]    Script Date: 12/04/2022 05:04:19 p. m. ******/SET ANSI_NULLS ONGOSET QUOTED_IDENTIFIER ONGO-- =============================================-- Author: Daniel AC-- Create date: 12-04-2022-- Description:	 Se cambian los aprobadores mostrados por los aprobadores de pedido, mostrando la columna Estatus-- =============================================CREATE  PROCEDURE [dbo].[SP_RPT_OCM_AprobadoresPorPedido]	@IdPedido INTASBEGIN	SELECT		'Aprobador ' + CAST(T.NoSecuencia AS NVARCHAR(max)) AS NoAprobador,		T.NoSecuencia, 		U.Nombre, 		t.FechaCambioEstatus, 		t.IdTarea,		t.IdFirma,		tae.Nombre as Estatus	FROM TA_Tarea AS T				INNER JOIN TA_Operacion AS TOO ON T.IdOperacion = TOO.IdOperacion		INNER JOIN dbo.MM_SolicitudPedido AS SP ON TOO.IdDocumento = SP.IdSolicitudPedido 		INNER JOIN dbo.MM_Pedido AS p ON sp.IdSolicitudPedido = p.IdSolicitudPedido  AND  too.NoVersion = p.Version		INNER JOIN S_Usuario AS U on T.IdAprobador = u.IdUsuario 		INNER JOIN TA_Estatus AS TAE ON T.IdEstatus = TAE.IdEstatus 	WHERE p.IdPedido = @IdPedido 		AND t.IdEstatus = 2 --> CTE APROBADO		AND TOO.IdTipoOperacion = 9 --> CTE APROBACION DE PEDIDO	ORDER BY NoSecuencia ASC 		END